@modal.concurrent(max_inputs=MAX_NUM_SEQS)
class QwenEndpoint:
    @modal.enter()
    def start(self) -> None:
        ensure_model_downloaded()
        self.multimodal_enabled = is_multimodal_model()
        self.engine_process = subprocess.Popen(
            engine_command(self.multimodal_enabled),
            stdin=subprocess.DEVNULL,
            stdout=None,
            stderr=None,
            env=os.environ.copy(),
            start_new_session=True,
        )
        atexit.register(self.stop)
        self.wait_for_engine()

    def wait_for_engine(self) -> None:
        deadline = time.monotonic() + STARTUP_TIMEOUT_SECONDS

        while time.monotonic() < deadline:
            if self.engine_process.poll() is not None:
                raise RuntimeError(
                    f"vLLM exited with code {self.engine_process.returncode}"
                )

            try:
                import httpx

                response = httpx.get(
                    f"{ENGINE_URL}/v1/models",
                    timeout=10,
                )
                response.raise_for_status()
                return
            except Exception:
                time.sleep(2)

        raise TimeoutError("vLLM startup timeout")

    def stop(self) -> None:
        stop_process(getattr(self, "engine_process", None))

    @modal.exit()
    def shutdown(self) -> None:
        self.stop()

    def authorized(self, request) -> None:
        supplied = request.headers.get("authorization", "")
        expected = os.environ["API_KEY"]

        if not supplied.startswith("Bearer ") or not hmac.compare_digest(
            supplied[7:],
            expected,
        ):
            from fastapi import HTTPException

            raise HTTPException(
                status_code=401,
                detail=error_payload(
                    "invalid API key",
                    "authentication_error",
                    "invalid_api_key",
                ),
            )

    async def proxy_stream(
        self,
        payload: dict[str, Any],
    ) -> AsyncIterator[bytes]:
        import httpx

        timeout = httpx.Timeout(
            connect=30,
            read=1800,
            write=30,
            pool=30,
        )

        async with httpx.AsyncClient(timeout=timeout) as client:
            async with client.stream(
                "POST",
                f"{ENGINE_URL}/v1/chat/completions",
                json=payload,
            ) as response:
                async for chunk in response.aiter_bytes():
                    yield chunk

    @modal.asgi_app()
    def web(self):
        import httpx
        from fastapi import FastAPI, HTTPException, Request
        from fastapi.responses import JSONResponse, StreamingResponse

        web_app = FastAPI()

        @web_app.exception_handler(HTTPException)
        async def handle_error(
            _: Request,
            exception: HTTPException,
        ):
            detail = (
                exception.detail
                if isinstance(exception.detail, dict)
                else error_payload(
                    str(exception.detail),
                    "invalid_request_error",
                    exception.status_code,
                )
            )
            return JSONResponse(
                status_code=exception.status_code,
                content=detail,
            )

        @web_app.post("/v1/chat/completions")
        async def completions(request: Request):
            self.authorized(request)

            content_length = request.headers.get("content-length")
            if content_length is not None:
                try:
                    declared_length = int(content_length)
                except ValueError as exc:
                    raise HTTPException(
                        status_code=400,
                        detail=error_payload(
                            "invalid content length",
                            "invalid_request_error",
                            "invalid_content_length",
                        ),
                    ) from exc

                if declared_length < 0 or declared_length > MAX_REQUEST_BYTES:
                    raise HTTPException(
                        status_code=413,
                        detail=error_payload(
                            "request too large",
                            "invalid_request_error",
                            "request_too_large",
                        ),
                    )

            body = await request.body()

            if len(body) > MAX_REQUEST_BYTES:
                raise HTTPException(
                    status_code=413,
                    detail=error_payload(
                        "request too large",
                        "invalid_request_error",
                        "request_too_large",
                    ),
                )

            try:
                decoded_payload = json.loads(body)
                payload = validate_payload(
                    decoded_payload,
                    self.multimodal_enabled,
                )
            except (
                json.JSONDecodeError,
                TypeError,
                ValueError,
            ) as exc:
                raise HTTPException(
                    status_code=400,
                    detail=error_payload(
                        str(exc),
                        "invalid_request_error",
                        "invalid_request",
                    ),
                ) from exc

            if payload.get("stream"):
                return StreamingResponse(
                    self.proxy_stream(payload),
                    media_type="text/event-stream",
                    headers={
                        "Cache-Control": "no-cache",
                        "Connection": "keep-alive",
                    },
                )

            try:
                timeout = httpx.Timeout(
                    connect=30,
                    read=1800,
                    write=30,
                    pool=30,
                )

                async with httpx.AsyncClient(timeout=timeout) as client:
                    response = await client.post(
                        f"{ENGINE_URL}/v1/chat/completions",
                        json=payload,
                    )

                try:
                    response_payload = response.json()
                except ValueError as exc:
                    return JSONResponse(
                        status_code=502,
                        content=error_payload(
                            str(exc),
                            "api_error",
                            "invalid_engine_response",
                        ),
                    )

                return JSONResponse(
                    status_code=response.status_code,
                    content=response_payload,
                )
            except httpx.HTTPError as exc:
                return JSONResponse(
                    status_code=503,
                    content=error_payload(
                        str(exc),
                        "api_error",
                        "engine_unavailable",
                    ),
                )

        @web_app.get("/health")
        async def health(request: Request):
            self.authorized(request)

            try:
                async with httpx.AsyncClient(
                    timeout=INFERENCE_HEALTH_TIMEOUT_SECONDS
                ) as client:
                    response = await client.get(f"{ENGINE_URL}/v1/models")

                response.raise_for_status()

                return {
                    "status": "ok",
                    "model": SERVED_MODEL_NAME,
                    "multimodal": self.multimodal_enabled,
                    "max_model_len": MAX_MODEL_LEN,
                    "max_concurrent_requests": MAX_NUM_SEQS,
                }
            except httpx.HTTPError as exc:
                return JSONResponse(
                    status_code=503,
                    content=error_payload(
                        str(exc),
                        "api_error",
                        "engine_unhealthy",
                    ),
                )

        return web_app


def call_modal(payload: dict[str, Any]) -> dict[str, Any]:
    if not MODAL_ENDPOINT_URL:
        raise RuntimeError("Modal endpoint is not configured")

    request_payload = dict(payload)
    request_payload["chat_template_kwargs"] = {
        **(
            payload.get("chat_template_kwargs")
            if isinstance(payload.get("chat_template_kwargs"), dict)
            else {}
        ),
        "enable_thinking": True,
    }

    request = UrlRequest(
        MODAL_ENDPOINT_URL + "/v1/chat/completions",
        data=json.dumps(request_payload).encode(),
        headers={
            "Content-Type": "application/json",
            "Authorization": f"Bearer {MODAL_API_KEY}",
        },
        method="POST",
    )

    try:
        with urlopen(request, timeout=1800) as response:
            decoded_response = json.loads(response.read())

        if not isinstance(decoded_response, dict):
            raise RuntimeError("Modal endpoint returned a non-object response")

        return decoded_response
    except HTTPError as exc:
        raise RuntimeError(
            exc.read().decode("utf-8", "replace")
        ) from exc
    except URLError as exc:
        raise RuntimeError(str(exc.reason)) from exc
    except json.JSONDecodeError as exc:
        raise RuntimeError("Modal endpoint returned invalid JSON") from exc


class LocalHandler(BaseHTTPRequestHandler):
    icon_svg = b"<svg xmlns=\"" viewBox=\"0 0 64 64\"><rect width=\"64\" height=\"64\" rx=\"22\" fill=\"#050510\"/><path d=\"M32 14c-10 0-18 6.7-18 15 0 4.6 2.5 8.7 6.4 11.4-.5 2.5-1.9 4.8-3.9 6.4 3.3-.3 6.4-1.4 9-3.2 2 .6 4.2.9 6.5.9 10 0 18-6.7 18-15S42 14 32 14z\" fill=\"#5f6af7\"/></svg>"
    manifest = b'{"name":"Chat","short_name":"Chat","start_url":"/","display":"standalone","background_color":"#050510","theme_color":"#050510","icons":[]}'
    transparent_png = base64.b64decode(
        "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII="
    )

    def send_json(
        self,
        status: int,
        payload: dict[str, Any],
    ) -> None:
        body = json.dumps(
            payload,
            ensure_ascii=False,
        ).encode()

        self.send_response(status)
        self.send_header(
            "Content-Type",
            "application/json; charset=utf-8",
        )
        self.send_header(
            "Content-Length",
            str(len(body)),
        )
        self.send_header(
            "Cache-Control",
            "no-store",
        )
        self.end_headers()
        try:
            self.wfile.write(body)
        except BrokenPipeError:
            return

    def do_GET(self) -> None:
        path = self.path.split("?", 1)[0]

        if path == "/api/health":
            self.send_json(
                200,
                {
                    "ok": True,
                    "modal": bool(MODAL_ENDPOINT_URL),
                },
            )
            return

        if path == "/manifest.webmanifest":
            body = self.manifest
            self.send_response(200)
            self.send_header("Content-Type", "application/manifest+json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
            return

        if path == "/favicon.ico" or path.startswith("/icons/"):
            body = self.icon_svg
            self.send_response(200)
            self.send_header("Content-Type", "image/svg+xml")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
            return

        if path.startswith("/splash/"):
            body = self.transparent_png
            self.send_response(200)
            self.send_header("Content-Type", "image/png")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
            return

        if path in {"/", "/index.html"}:
            try:
                body = Path(__file__).with_name("index.html").read_bytes()
            except OSError as exc:
                self.send_json(
                    500,
                    {
                        "error": {
                            "message": str(exc),
                        }
                    },
                )
                return

            self.send_response(200)
            self.send_header(
                "Content-Type",
                "text/html; charset=utf-8",
            )
            self.send_header(
                "Cache-Control",
                "no-store",
            )
            self.send_header(
                "Content-Length",
                str(len(body)),
            )
            self.end_headers()
            self.wfile.write(body)
            return

        self.send_error(404)

    def do_POST(self) -> None:
        path = self.path.split("?", 1)[0]
        if path != "/api/chat":
            self.send_error(404)
            return

        try:
            content_length = self.headers.get("Content-Length")
            if content_length is None:
                raise ValueError("missing content length")

            length = int(content_length)
            if length <= 0 or length > MAX_REQUEST_BYTES:
                raise ValueError("invalid request size")

            raw_payload = self.rfile.read(length)
            payload = json.loads(raw_payload)

            if not isinstance(payload, dict):
                raise ValueError("request body must be a JSON object")

            messages = payload.get("messages")
            if not isinstance(messages, list) or not messages:
                raise ValueError("messages must be a non-empty array")

            self.send_json(200, call_modal(payload))
        except (
            ValueError,
            TypeError,
            json.JSONDecodeError,
        ) as exc:
            self.send_json(
                400,
                {
                    "error": {
                        "message": str(exc),
                    }
                },
            )
        except Exception as exc:
            self.send_json(
                502,
                {
                    "error": {
                        "message": str(exc),
                    }
                },
            )

    def log_message(
        self,
        format: str,
        *args: Any,
    ) -> None:
        return


class ReusableThreadingHTTPServer(ThreadingHTTPServer):
    allow_reuse_address = True
    allow_reuse_port = True
    daemon_threads = True


def run_local() -> None:
    if LOCAL_PORT == 0:
        candidate_ports = (0,)
    else:
        candidate_ports = range(LOCAL_PORT, 65536)

    server = None
    last_error = None

    for candidate_port in candidate_ports:
        try:
            server = ReusableThreadingHTTPServer(
                ("0.0.0.0", candidate_port),
                LocalHandler,
            )
            break
        except OSError as exc:
            if exc.errno != errno.EADDRINUSE:
                raise
            last_error = exc

    if server is None:
        if last_error is not None:
            raise last_error
        raise OSError(errno.EADDRINUSE, "no available local port")

    try:
        server.serve_forever()
    finally:
        server.server_close()


if __name__ == "__main__":
    run_local()

