        raise RuntimeError(f"Model metadata is empty: {MODEL_ID}")

    model_path = Path(MODEL_DIR)
    complete = model_path.is_dir() and all(
        (model_path / name).is_file() and (model_path / name).stat().st_size == size
        for name, size in expected.items()
    )

    if not complete:
        model_path.mkdir(parents=True, exist_ok=True)
        snapshot_download(
            repo_id=MODEL_ID,
            local_dir=MODEL_DIR,
            token=token,
        )
        complete = all(
            (model_path / name).is_file() and (model_path / name).stat().st_size == size
            for name, size in expected.items()
        )
        if not complete:
            raise RuntimeError(f"Incomplete model download: {MODEL_ID}")
        model_volume.commit()


def is_multimodal_model() -> bool:
    config_path = Path(MODEL_DIR) / "config.json"
    processor_path = Path(MODEL_DIR) / "preprocessor_config.json"

    if not config_path.is_file() or not processor_path.is_file():
        return False

    try:
        config = json.loads(config_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return False

    values = [str(config.get("model_type", "")).lower()]
    values.extend(str(value).lower() for value in config.get("architectures", []))
    return any("vision" in value or "vl" in value for value in values)


def engine_command(multimodal: bool) -> list[str]:
    command = [
        "vllm",
        "serve",
        MODEL_DIR,
        "--served-model-name",
        SERVED_MODEL_NAME,
        "--host",
        ENGINE_HOST,
        "--port",
        str(ENGINE_PORT),
        "--tensor-parallel-size",
        "1",
        "--max-model-len",
        str(MAX_MODEL_LEN),
        "--max-num-seqs",
        str(MAX_NUM_SEQS),
        "--max-num-batched-tokens",
        str(MAX_NUM_BATCHED_TOKENS),
        "--gpu-memory-utilization",
        "0.95",
        "--dtype",
        "bfloat16",
        "--kv-cache-dtype",
        "fp8",
        "--enable-prefix-caching",
        "--enforce-eager",
        "--trust-remote-code",
    ]

    if multimodal:
        command.extend(["--limit-mm-per-prompt", '{"image": 8, "video": 2}'])

    return command


def error_payload(
    message: str,
    error_type: str,
    code: int | str | None = None,
) -> dict[str, Any]:
    return {
        "error": {
            "message": message,
            "type": error_type,
            "param": None,
            "code": code,
        }
    }


def validate_payload(
    payload: dict[str, Any],
    multimodal: bool,
) -> dict[str, Any]:
    if not isinstance(payload, dict):
        raise ValueError("request body must be a JSON object")

    sanitized = dict(payload)
    sanitized["model"] = SERVED_MODEL_NAME

    messages = sanitized.get("messages")
    if not isinstance(messages, list) or not messages:
        raise ValueError("messages must be a non-empty array")

    max_tokens = sanitized.get(
        "max_tokens",
        sanitized.get("max_completion_tokens", 4096),
    )

    if (
        not isinstance(max_tokens, int)
        or isinstance(max_tokens, bool)
        or not 1 <= max_tokens <= MAX_COMPLETION_TOKENS
    ):
        raise ValueError(
            f"max_tokens must be an integer between 1 and {MAX_COMPLETION_TOKENS}"
        )

    contains_media = any(
        isinstance(item, dict)
        and isinstance(item.get("content"), list)
        and any(
            isinstance(part, dict)
            and str(part.get("type", "")).startswith(("image", "video"))
            for part in item["content"]
        )
        for item in messages
        if isinstance(item, dict)
    )

    if contains_media and not multimodal:
        raise ValueError("multimodal inference is unavailable")

    sanitized["max_tokens"] = max_tokens
    sanitized.pop("max_completion_tokens", None)
    return sanitized


def stop_process(process: subprocess.Popen[bytes] | None) -> None:
    if process is None or process.poll() is not None:
        return

    try:
        os.killpg(process.pid, signal.SIGTERM)
        process.wait(timeout=30)
    except (ProcessLookupError, subprocess.TimeoutExpired):
        try:
            os.killpg(process.pid, signal.SIGKILL)
        except ProcessLookupError:
            return

        try:
            process.wait(timeout=30)
        except subprocess.TimeoutExpired:
            return


